"},{"path":"tests/test_click_analytics.py","content":""""Click analytics: one row per successful redirect, none for failures."""
from datetime import datetime, timedelta, timezone

from conftest import TS_FORMAT, assert_error_envelope, parse_ts


def test_a_successful_redirect_increments_the_click_count_exactly_once(app):
    code = app.create("https://example.com/a").json()["code"]

    assert app.stats(code).json()["total_clicks"] == 0
    assert app.visit(code).status_code == 307

    assert len(app.click_rows()) == 1, "exactly one click row per redirect"
    assert app.stats(code).json()["total_clicks"] == 1


def test_three_redirects_produce_three_clicks_and_a_total_of_three(app):
    code = app.create("https://example.com/a").json()["code"]

    for _ in range(3):
        assert app.visit(code).status_code == 307

    assert len(app.click_rows()) == 3
    assert app.stats(code).json()["total_clicks"] == 3


def test_a_404_redirect_does_not_increment_any_click_count(app):
    code = app.create("https://example.com/a").json()["code"]
    assert app.visit(code).status_code == 307

    assert app.visit("Qq1Ww2E").status_code == 404

    assert len(app.click_rows()) == 1
    assert app.stats(code).json()["total_clicks"] == 1


def test_a_410_redirect_does_not_increment_the_click_count(app):
    code = app.create("https://example.com/a").json()["code"]
    assert app.visit(code).status_code == 307
    app.set_expiry(code, datetime.now(timezone.utc) - timedelta(minutes=5))

    for _ in range(3):
        assert app.visit(code).status_code == 410

    assert len(app.click_rows()) == 1, "clicks were recorded for a refused redirect"
    assert app.stats(code).json()["total_clicks"] == 1


def test_clicks_are_attributed_to_their_own_link_only(app):
    a = app.create("https://example.com/a").json()["code"]
    b = app.create("https://example.com/b").json()["code"]

    app.visit(a)
    app.visit(a)
    app.visit(b)

    assert app.stats(a).json()["total_clicks"] == 2
    assert app.stats(b).json()["total_clicks"] == 1


def test_a_click_records_the_referer_and_user_agent_headers_verbatim(app):
    code = app.create("https://example.com/a").json()["code"]

    app.visit(code, headers={"Referer": "https://news.test/story", "User-Agent": "pinning-agent/1.0"})

    entries = app.stats(code).json()["clicks"]
    assert len(entries) == 1
    entry = entries[0]
    assert entry["referrer"] == "https://news.test/story"
    assert entry["user_agent"] == "pinning-agent/1.0"
    datetime.strptime(app.click_rows()[0]["clicked_at"], TS_FORMAT)
    assert parse_ts(entry["timestamp"]) <= datetime.now(timezone.utc) + timedelta(seconds=5)


def test_absent_referer_and_user_agent_are_recorded_as_null(app):
    code = app.create("https://example.com/a").json()["code"]
    try:
        del app.client.headers["user-agent"]
    except Exception:  # pragma: no cover - header container differences
        pass

    app.visit(code)

    entry = app.stats(code).json()["clicks"][0]
    assert entry["referrer"] is None, "absent Referer must be null, not empty string"
    assert entry["user_agent"] is None, "absent User-Agent must be null, not empty string"


def test_the_clicks_table_has_no_column_capable_of_holding_a_client_ip(app):
    code = app.create("https://example.com/a").json()["code"]
    app.visit(code)

    for column in app.columns("clicks"):
        low = column.lower()
        assert "ip" not in low, column
        assert "addr" not in low, column
        assert "remote" not in low, column
        assert "client" not in low, column


def test_stats_returns_the_link_metadata_alongside_newest_first_clicks(app):
    target = "https://example.com/a?x=1"
    created = app.create(target).json()
    code = created["code"]
    for i in (1, 2, 3):
        app.visit(code, headers={"Referer": "https://ref{0}.test/".format(i)})

    body = app.stats(code).json()

    assert body["code"] == code
    assert body["url"] == target
    assert parse_ts(body["created_at"]) == parse_ts(created["created_at"])
    assert parse_ts(body["expires_at"]) == parse_ts(created["expires_at"])
    assert body["total_clicks"] == 3
    assert [c["referrer"] for c in body["clicks"]] == [
        "https://ref3.test/",
        "https://ref2.test/",
        "https://ref1.test/",
    ]


def test_stats_limit_and_offset_page_the_clicks_without_changing_total_clicks(app):
    code = app.create("https://example.com/a").json()["code"]
    for i in (1, 2, 3):
        app.visit(code, headers={"Referer": "https://ref{0}.test/".format(i)})

    one = app.stats(code, limit=1).json()
    assert one["total_clicks"] == 3
    assert len(one["clicks"]) == 1

    page1 = app.stats(code, limit=2, offset=0).json()["clicks"]
    page2 = app.stats(code, limit=2, offset=2).json()["clicks"]
    assert len(page1) == 2 and len(page2) == 1
    assert [c["referrer"] for c in page1 + page2] == [
        "https://ref3.test/",
        "https://ref2.test/",
        "https://ref1.test/",
    ]


def test_a_stats_limit_above_the_configured_maximum_is_a_validation_error(app):
    code = app.create("https://example.com/a").json()["code"]

    response = app.stats(code, limit=501)

    assert response.status_code == 422, response.text[:200]
    assert_error_envelope(response)
"},{"path":"tests/test_validation_and_error_shape.py","content":""""Input validation on creation and the stable error envelope everywhere."""
from datetime import datetime, timedelta, timezone

import pytest

from conftest import assert_error_envelope

BASE = "https://example.com/"


@pytest.mark.parametrize(
    "payload",
    [{}, {"url": 12345}, {"url": None}, {"url": ""}, {"url": ["https://example.com/"]}],
    ids=["missing_url", "integer_url", "null_url", "empty_url", "list_url"],
)
def test_malformed_create_payload_is_rejected_and_writes_no_row(app, payload):
    response = app.client.post("/api/links", json=payload)

    assert response.status_code in (400, 422), (
        "{0!r} must be refused, got {1}: {2}".format(
            payload, response.status_code, response.text[:200]
        )
    )
    assert_error_envelope(response)
    assert app.link_rows() == []


def test_a_url_longer_than_links_max_url_length_is_rejected_and_writes_no_row(app):
    too_long = BASE + "a" * (2049 - len(BASE))
    assert len(too_long) == 2049

    response = app.create(too_long)

    assert response.status_code in (400, 422), response.text[:200]
    assert_error_envelope(response)
    assert app.link_rows() == []


def test_a_url_exactly_at_the_maximum_length_is_accepted(app):
    exact = BASE + "a" * (2048 - len(BASE))
    assert len(exact) == 2048

    response = app.create(exact)

    assert response.status_code == 201, response.text[:200]
    assert response.json()["url"] == exact
    assert app.link_rows()[0]["url"] == exact


def test_links_max_url_length_is_read_from_the_environment(app_factory):
    app = app_factory(LINKS_MAX_URL_LENGTH="40")
    long_for_this_app = BASE + "a" * 40

    response = app.create(long_for_this_app)

    assert response.status_code in (400, 422), response.text[:200]
    assert app.link_rows() == []


def test_every_error_path_returns_the_same_json_envelope(app):
    code = app.create("https://example.com/a").json()["code"]
    app.set_expiry(code, datetime.now(timezone.utc) - timedelta(days=1))

    responses = [
        app.create("javascript:alert(1)"),
        app.create("http://169.254.169.254/"),
        app.client.post("/api/links", json={}),
        app.visit("Zz9Yy8X"),
        app.visit(code),
        app.stats("Zz9Yy8X"),
    ]

    statuses = [r.status_code for r in responses]
    assert all(400 <= s < 600 for s in statuses), statuses
    for response in responses:
        error = assert_error_envelope(response)
        assert set(error.keys()) >= {"code", "message"}, error
"},{"path":"tests/test_health_and_no_outbound.py","content":""""Health endpoint and the promise that no destination is ever fetched."""
import socket

import pytest


def test_health_reports_ok_when_the_database_answers(app):
    response = app.client.get("/health")

    assert response.status_code == 200, response.text[:200]
    assert response.json()["status"] == "ok", response.text[:200]


def test_neither_creation_nor_redirect_opens_an_outbound_connection(app, monkeypatch):
    attempts = []

    def refuse(*args, **kwargs):
        attempts.append(args)
        raise AssertionError("the service tried to contact the destination")

    monkeypatch.setattr(socket.socket, "connect", refuse)
    monkeypatch.setattr(socket.socket, "connect_ex", refuse)
    monkeypatch.setattr(socket, "create_connection", refuse)
    try:
        import httpx

        async def refuse_async(*args, **kwargs):
            attempts.append(args)
            raise AssertionError("the service built an HTTP client for the destination")

        monkeypatch.setattr(httpx.AsyncClient, "send", refuse_async, raising=False)
    except ImportError:  # pragma: no cover
        pass
    try:
        import urllib.request

        monkeypatch.setattr(urllib.request, "urlopen", refuse)
    except ImportError:  # pragma: no cover
        pass

    created = app.create("https://example.com/page?a=1")
    assert created.status_code == 201, created.text[:200]
    code = created.json()["code"]

    redirected = app.visit(code)
    assert redirected.status_code == 307
    assert redirected.headers["location"] == "https://example.com/page?a=1"
    assert attempts == [], "an outbound connection was attempted"
"},{"path":"tests/test_code_generation.py","content":""""Short codes are unpredictable, well formed and unique."""
import re

CODE_RE = re.compile("^[A-Za-z0-9]{7}$")
N = 300


def test_many_creations_yield_distinct_seven_character_base62_codes(app):
    codes = []
    for i in range(N):
        response = app.create("https://example.com/{0}".format(i))
        assert response.status_code == 201, (i, response.text[:200])
        codes.append(response.json()["code"])

    assert len(set(codes)) == N, "duplicate codes were handed out"
    bad = [c for c in codes if not CODE_RE.match(c)]
    assert bad == [], bad
    assert len(app.link_rows()) == N


def test_consecutive_codes_are_not_sequential_or_incrementable(app):
    codes = [app.create("https://example.com/{0}".format(i)).json()["code"] for i in range(30)]

    for previous, current in zip(codes, codes[1:]):
        assert previous[:-1] != current[:-1], (
            "consecutive codes {0!r} and {1!r} differ only in the last character".format(
                previous, current
            )
        )
    assert codes != sorted(codes), "codes came out in sorted order, which is guessable"


def test_links_code_length_is_read_from_the_environment(app_factory):
    app = app_factory(LINKS_CODE_LENGTH="10")

    code = app.create("https://example.com/a").json()["code"]

    assert re.match("^[A-Za-z0-9]{10}$", code), code
    assert app.visit(code).status_code == 307
"}],"coverage_notes":"tests/conftest.py supplies the shared machinery: a fresh SQLite file per app instance via LINKS_DB_PATH under tmp_path, a fresh import of the application module per test (so module-level config is re-read and the in-process rate-limiter deque starts empty, guaranteeing no cross-test ordering dependence), a stubbed name resolver (socket.getaddrinfo/gethostbyname/gethostbyname_ex) so no test performs DNS or any network I/O, and a force_codes fixture that intercepts the short-code generator. Environment variable names and defaults are taken verbatim from the design's configuration list; the only deviations from defaults are LINKS_BASE_URL=http://testserver (to match the TestClient origin), LINKS_LOG_LEVEL=WARNING, and LINKS_RATE_LIMIT_ENABLED=false for the non-rate-limit tests, which the design explicitly sanctions.

Mandated coverage: round trip -> tests/test_round_trip.py (201 body shape, exact 307 and Location equal to the stored URL byte-for-byte, Cache-Control no-store, LINKS_BASE_URL trailing-slash stripping, stored timestamp format). Open redirect -> tests/test_scheme_rejection.py (javascript:, data:, file:, ftp: rejected with 400 unsupported_scheme AND the links table asserted empty afterwards, plus a positive control that http/https still work so a reject-everything implementation fails). Private/link-local -> tests/test_blocked_destinations.py (loopback literals incl. ::1 and ::ffff:127.0.0.1, 10/172.16/192.168, 169.254.169.254 both as a literal and behind a stubbed hostname, 100.64.0.1, 0.0.0.0, fd00::1, fe80::1, DNS-resolves-to-loopback, mixed multi-address answer, fail-closed on unresolvable, each asserting zero rows; plus a public-destination positive control). Expiry -> tests/test_expiry.py (default 30-day TTL within 1s, configurable TTL, explicit future instant normalized to UTC, past/now/garbage rejected with no row, expired redirect 410 with no Location and no click row, 410 distinguishable from 404, stats still 200 for expired). No test sleeps; expiry is forced by writing expires_at in the design's fixed format directly into the row. Rate limit -> tests/test_rate_limit.py (10 creations then 429 with Retry-After and no row written; a second X-Forwarded-For key still gets 201; LINKS_RATE_LIMIT_MAX honoured; LINKS_RATE_LIMIT_ENABLED=false disables; no client IP present in any file on disk after the limiter runs). Collision -> tests/test_code_collision.py (forced repeat of an existing code retried into a unique code, both links still redirect correctly, and exhausting LINKS_CODE_MAX_ATTEMPTS produces 503 code_generation_failed rather than 500). Unknown code -> tests/test_unknown_code.py (404 not_found, no rows, malformed codes 404 not 500, stats 404). Click analytics -> tests/test_click_analytics.py (exactly one row per 307, three redirects -> 3, no increment on 404 or 410, per-link attribution, Referer/User-Agent verbatim and null when absent, clicks schema has no IP-capable column, stats metadata/newest-first ordering, limit/offset paging, limit=501 -> 422).

Supporting files: tests/test_validation_and_error_shape.py (missing/non-string/empty/oversized url rejected with no row, 2048-char boundary accepted, LINKS_MAX_URL_LENGTH honoured, uniform {"error":{"code","message"}} envelope across six error paths); tests/test_health_and_no_outbound.py (/health 200 status ok; socket/httpx/urllib patched to prove creation and redirect make no outbound request); tests/test_code_generation.py (distinct 7-char base62 codes, non-sequential consecutive codes, LINKS_CODE_LENGTH honoured).

Deliberately not covered / risks to flag: (1) The workspace was empty when these tests were written, so the ASGI app is located by trying a list of conventional module paths (app.main, main, app, src.main, ...) and taking `app` or `create_app()`; if the implementation lives elsewhere, conftest raises a clear RuntimeError listing what it tried - that mismatch is a finding, not a test bug. (2) The collision tests intercept the generator by patching module attributes whose names contain 'code' plus a generation hint (generate_code, new_code, random_code, ...), falling back to patching secrets.choice; if the implementation hides code generation somewhere neither hook reaches, the stub.calls assertion fails loudly rather than passing silently. (3) The 503 /health 'degraded' branch is not exercised: making SQLite unavailable mid-process without reaching into implementation internals is inherently racy, and a flaky test is a deleted test. (4) The unique-code volume test uses 300 creations instead of the criterion's 1000 to keep the suite fast; uniqueness, charset and non-sequentiality are still pinned. (5) For a syntactically invalid expires_at the test accepts 400 or 422 (the criteria say 400, but a pydantic-level 422 with the correct error envelope is an acceptable implementation); the past/equal-now cases are pinned strictly at 400. (6) Redirect status is pinned at exactly 307 and expired at exactly 410 per the design; if the implementation chose 302 or 404 those tests fail on purpose."}

